"""Errors and the ordered notification log (C32)."""


class DepotError(Exception):
    """A failed depot operation. `code` is a string such as "CAPACITY"."""

    def __init__(self, code):
        super().__init__(code)
        self.code = code


class EventLog:
    """Append-only, ordered list of notification tuples."""

    def __init__(self, items=None):
        self._items = [tuple(i) for i in items] if items else []

    def emit(self, *args):
        self._items.append(tuple(args))

    def items(self):
        return list(self._items)
