"""Money rules: integer cents, rounding, list prices, bulk discounts,
storage and transfer charges, and turnover (C08, C09, C11, C19, C30).

Configuration is read from data.toml next to this file.
"""

import pathlib
import tomllib
from decimal import Decimal
from fractions import Fraction

from events import DepotError

_DATA = tomllib.loads(
    (pathlib.Path(__file__).resolve().parent / "data.toml").read_text(encoding="utf-8")
)

MARKUP = Decimal(str(_DATA["markup"]))
BULK_THRESHOLD = int(_DATA["bulk_threshold"])
BULK_DISCOUNT_PCT = Decimal(str(_DATA["bulk_discount_pct"]))
STORAGE_CENTS_PER_UNIT_DAY = int(_DATA["storage_cents_per_unit_day"])
TRANSFER_CENTS_PER_UNIT = int(_DATA["transfer_credit_cents_per_unit"])


def to_cents(value, mode):
    """Round a number (int, float, str, Decimal) to a whole cent with a decimal rounding mode."""
    d = Decimal(str(value))
    return int(d.quantize(Decimal(1), rounding=mode))


def list_price(unit_cost, mode):
    """C08: unit_cost * (1 + markup), rounded to a whole cent."""
    return to_cents(Decimal(unit_cost) * (1 + MARKUP), mode)


def sale_revenue(price, qty, mode):
    """C07/C09: price * qty, with bulk discount for qty >= bulk_threshold."""
    gross = Decimal(price) * qty
    if qty >= BULK_THRESHOLD:
        gross = gross * (100 - BULK_DISCOUNT_PCT) / 100
    return to_cents(gross, mode)


def storage_charge(units):
    """C19: storage cost for all units held over one day."""
    return STORAGE_CENTS_PER_UNIT_DAY * units


def transfer_cost(qty):
    """C11: cost borne by the sending side of a transfer."""
    return TRANSFER_CENTS_PER_UNIT * qty


class Ledger:
    """Cash plus the history needed for turnover (C30)."""

    def __init__(self, cash):
        self.cash = cash
        self.shipments = []   # list of (day, qty)
        self.holdings = {}    # closed day -> units held during that day

    def turnover(self, start_day, end_day):
        """Units shipped in [start_day, end_day] divided by average units held.

        The average is taken over closed days in the range. Returns None when
        the average is 0.
        """
        if start_day > end_day:
            raise DepotError("BAD_ARG")
        shipped = sum(q for d, q in self.shipments if start_day <= d <= end_day)
        samples = [self.holdings[d] for d in range(start_day, end_day + 1) if d in self.holdings]
        total = sum(samples)
        if not samples or total == 0:
            return None
        return float(Fraction(shipped) * len(samples) / total)
