"""Suppliers, reliability and purchase orders (C15, C16, C17)."""

from events import DepotError

_START_RELIABILITY = 3
_MIN_RELIABILITY = 0
_MAX_RELIABILITY = 5
_SUSPENDED_AT = 1      # reliability <= this means suspended
_REINSTATED_TO = 2


class Suppliers:
    def __init__(self):
        self.rel = {}      # supplier -> reliability
        self.orders = {}   # order id -> dict
        self.next_id = 1

    # --- reliability -------------------------------------------------
    def reliability(self, name):
        if name not in self.rel:
            raise DepotError("UNKNOWN_SUPPLIER")
        return self.rel[name]

    def check_orderable(self, name):
        if name in self.rel and self.rel[name] <= _SUSPENDED_AT:
            raise DepotError("SUPPLIER_SUSPENDED")

    def adjust(self, name, late):
        """Apply C15. Returns (old, new) reliability."""
        old = self.rel[name]
        step = -1 if late else 1
        new = max(_MIN_RELIABILITY, min(_MAX_RELIABILITY, old + step))
        self.rel[name] = new
        return old, new

    def reinstate(self, name):
        if name not in self.rel:
            raise DepotError("UNKNOWN_SUPPLIER")
        self.rel[name] = _REINSTATED_TO

    # --- orders ------------------------------------------------------
    def add_order(self, name, sku, qty, due_day, wh):
        self.rel.setdefault(name, _START_RELIABILITY)
        oid = self.next_id
        self.next_id += 1
        self.orders[oid] = {
            "supplier": name,
            "sku": sku,
            "qty": qty,
            "due_day": due_day,
            "wh": wh,
            "delivered": False,
        }
        return oid

    def open_order(self, oid):
        if oid not in self.orders:
            raise DepotError("UNKNOWN_ORDER")
        o = self.orders[oid]
        if o["delivered"]:
            raise DepotError("ORDER_CLOSED")
        return dict(o)

    def mark_delivered(self, oid):
        self.orders[oid]["delivered"] = True

    # --- persistence -------------------------------------------------
    def to_dict(self):
        return {
            "reliability": dict(sorted(self.rel.items())),
            "orders": {str(k): dict(v) for k, v in sorted(self.orders.items())},
            "next_id": self.next_id,
        }

    @classmethod
    def from_dict(cls, d):
        obj = cls()
        obj.rel = {str(k): int(v) for k, v in d["reliability"].items()}
        obj.orders = {int(k): dict(v) for k, v in d["orders"].items()}
        obj.next_id = int(d["next_id"])
        return obj
